#!/usr/bin/env python3
"""Generates FirstFloor.ModernUI/Windows/Attached/T.cs: state properties used by styles converted from WPF's DataTriggers."""
import sys
n = int(sys.argv[1]) if len(sys.argv) > 1 else 400
out = [
    'using Avalonia;',
    '',
    'namespace FirstFloor.ModernUI.Windows.Attached {',
    '    /// <summary>',
    '    /// State properties used by styles converted from WPF’s DataTriggers (generated by PortTools/gen_state_props.py).',
    '    /// </summary>',
    '    public sealed class T {',
    '        private T() { }',
]
for i in range(n):
    out.append(f'        public static readonly AttachedProperty<bool> S{i}Property = AvaloniaProperty.RegisterAttached<T, AvaloniaObject, bool>("S{i}");')
    out.append(f'        public static bool GetS{i}(AvaloniaObject o) => o.GetValue(S{i}Property);')
    out.append(f'        public static void SetS{i}(AvaloniaObject o, bool v) => o.SetValue(S{i}Property, v);')
out += ['    }', '}']
open('/project/FirstFloor.ModernUI/Windows/Attached/T.cs', 'w').write('\n'.join(out) + '\n')
